@page "/inventory"
@rendermode InteractiveServer

@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _persistSub;

    private const string PersistKey = "equipment-items";

    protected override async Task OnInitializedAsync()
    {
        // Register a callback so prerender can persist the data before the
        // response completes.  This runs only during the static SSR pass.
        _persistSub = ApplicationState.RegisterOnPersisting(PersistData);

        // If the data was already persisted during prerender, reuse it
        // instead of calling the service again.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                PersistKey, out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson(PersistKey, _items);
        return Task.CompletedTask;
    }

    public void Dispose() => _persistSub.Dispose();
}

